select id, plan, monthly_fee, status, last_value(monthly_fee, true) over w_running as last_known_monthly_fee, first_value(monthly_fee, true) over w_part as first_known_monthly_fee from subscriptions window w_running as (order by end_date, id rows between unbounded preceding and current row), w_part as (partition by customer_id order by start_date, id rows between unbounded preceding and current row);
